def eulerian_num(n, m):
    if n == 0:
        return 0
    if m < 0 or m >= n:
        return 0
    if m == 0:
        return 1 if n == 1 else 0
    if m == n - 1:
        return 1

    # Dynamic Programming approach
    dp = [[0] * n for _ in range(n)]

    # Base case a(1, 0) = 1
    dp[1][0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            if i == 1 and j == 0:
                continue
            if j == 0:
                dp[i][j] = 0 # a(n, 0) = 0 for n > 1
            elif j == i - 1:
                dp[i][j] = 1
            else:
                # a(n, m) = m * a(n-1, m) + (n - m) * a(n-1, m-1)
                dp[i][j] = j * dp[i-1][j] + (i - 1 - j) * dp[i-1][j-1]

    return dp[n][m]

