def get_total_number_of_sequences(m,n): 
	T=[[0 for i in range(n+1)] for i in range(m+1)] 
	for j in range(1, n+1):
		for i in range(m+1):
			if j==1: 
				T[i][j]=1
			else: 
				limit_p = i // 2
				sum_prev = 0
				for p in range(limit_p + 1):
					sum_prev += T[p][j-1]
				T[i][j] = sum_prev
	return sum(T[i][n] for i in range(m+1))

